const DotBand: React.FC<{ frame: number }> = ({ frame }) => {
  const drift = ambientDrift(frame, 4, 200, "dot-band");
  const rows = 4;
  const cols = 36;
  const dots: React.ReactNode[] = [];
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      const opacity =
        0.08 +
        0.18 *
          ((Math.sin((c + r * 3 + frame * 0.04) * 0.7) + 1) / 2) *
          (1 - r / rows);
      dots.push(
        <div
          key={`${r}-${c}`}
          style={{
            position: "absolute",
            left: `${(c / (cols - 1)) * 100}%`,
            bottom: 20 + r * 28,
            width: 4,
            height: 4,
            borderRadius: 2,
            background: COLORS.orange,
            opacity,
            transform: "translateX(-50%)",
          }}
        />
      );
    }
  }
  return (
    <div
      style={{
        position: "absolute",
        left: 0,
        right: 0,
        bottom: 0,
        height: 160,
        pointerEvents: "none",
        transform: `translateX(${drift}px)`,
      }}
    >
      {dots}
    </div>
  );
};

